SELECT COUNT(*) FROM ticket t WHERE t.tenant_id = #{tenantId} AND t.status IN ('AWAITING_APPROVAL','PENDING_ASSIGNMENT','ASSIGNED','IN_PROGRESS')

  AND t.requester_user_id = #{scopeId}
  AND t.assignee_user_id = #{scopeId}
  AND (t.requester_user_id = #{scopeId} OR t.assignee_user_id = #{scopeId})
